function removeDuplicates(nums: number[]): number {
  // Первый элемент всегда уникален, поэтому писать начинаем с индекса 1
  let k = 1;

  for (let i = 1; i < nums.length; i++) {
    // Массив отсортирован: дубликаты стоят подряд, значит
    // новое значение — то, что отличается от последнего записанного
    if (nums[i] !== nums[k - 1]) {
      nums[k] = nums[i];
      k++;
    }
  }

  // В nums[0..k-1] — все уникальные значения по возрастанию
  return k;
}

// Время: O(n) — один проход
// Память: O(1) — меняем массив на месте
